if.description:
Evaluates the triggers if the display_triggers of the limit are met
if = { limit = { <display_triggers> } <triggers> }
Supported Scopes: all

switch.description:
Switch case for a trigger
switch = {
	trigger = has_ethic
	ethic_xenophile = { <trigger> }
	ethic_xenophobe = { <trigger> }
	default = { <trigger> }
}
Supported Scopes: all

closest_system.description:
Finds the closest system within the given hyperlane steps and limit = { <triggers> }. If this system does not exist, it returns false. If it does exist, it is checked against the triggers outside of the limit = {}.
closest_system = {
	limit = { <triggers> }
	min_steps = 2
	max_steps = 20
	use_bypasses = yes/no (default: no)
	<triggers>
}
Supported Scopes: all

else_if.description:
Evaluates the enclosed triggers if the display_triggers of the preceding `if` or `else_if` is not met and its own display_trigger of the limit is met
if = { limit = { <display_triggers> } <triggers> }
else_if = { limit = { <display_triggers> } <triggers> }
Supported Scopes: all

num_leader_traits.description:
Checks the number of leader traits or total tiers of traits for a specific leader
num_leader_traits = {  value > 2/variable  is_councilor = <any(default)/yes(only)/no(only)> negative <any(default)/no(only)/yes(only)>  count_tiers = <yes/no(default)> contains_modifier = { string = "federation" type=<any(default)/yes(only)/no(only) # filters on whether the trait has a modifier that contains the string "string"is_subclass = <any(default)/yes(only)/no(only) }
Supported Scopes: leader

get_councilor_level.description:
Get the level of a specific councilor 
get_councilor_level = { type = <key> }
Supported Scopes: country

num_favors.description:
Check amount of favors that scoped country can collect from target country:
num_favors = {
	target = <country>
	value ><= <value>/<variable>
}
Supported Scopes: country

num_ships_in_debris.description:
Checks the number of ships of a ship size in debris
num_ships_in_debris = { ship_size = corvette value > 15 }
Supported Scopes: debris

opinion.description:
Checks the country's opinion of the target country
opinion = { who = <target> value = -70/variable }
Supported Scopes: country

opinion_level.description:
Checks the country's opinion level of the target country (with support for comparison operators)
opinion_level = { who = <target> level >= neutral }
Supported Scopes: country

envoy_opinion_change.description:
Checks the country's opinion of the target country has been changed by envoys
envoy_opinion_change = { who = <target> value >= 25/variable }
Supported Scopes: country

intel.description:
Checks the country's Intel on the target country
intel = { who = <target> value = 70/variable }
Supported Scopes: country

tech_unlocked_ratio.description:
Checks the relative amount of already-researched tech between the country and target country
tech_unlocked_ratio = { who = <target> ratio = 0.4/variable }
Supported Scopes: country

can_colonize.description:
Checks if the planet can be colonized by target country
can_colonize = { who = <target> status = yes }
Supported Scopes: planet ship

is_point_of_interest.description:
Checks if the planet/country/ship/system/ambient object has a point of interest for a country. id and event_chain are optional; when omitted, matches any point of interest located at the scope for the owner.
is_point_of_interest = { owner = <target> } or { id = <id> event_chain = <event_chain> owner = <target> }
Supported Scopes: planet country ship galactic_object ambient_object

has_intel_level.description:
Checks the country's intel level on a category for the target country
has_intel_level = { who = <target> category = economy level = 2/variable }
Supported Scopes: country

has_intel_report.description:
Checks if the country has intel report of at least the specified level on a category for the target country
has_intel_report = { who = <target> category = economy level = 2/variable }
Supported Scopes: country

has_intel.description:
Checks if the specified intel is available for the target country (stale intel will not return true)
has_intel = { who = <target> intel = system_low_intel }
Supported Scopes: country

has_stale_intel.description:
Checks if the specified intel is stale for the target country (available intel will not return true)
has_stale_intel = { who = <target> intel = system_low_intel }
Supported Scopes: country

trust.description:
Checks the country's trust of the target country
trust = { who = <target> value = 50/variable }
Supported Scopes: country

hidden_trigger.description:
Hides the tooltip for the triggers within
hidden_trigger = { <triggers> }
Supported Scopes: all

has_civic_in_slot.description:
Checks if the country has a civic in a slot 
has_civic_in_slot = { civic = civic_galactic_sovereign index = 2 }
Supported Scopes: country

branch_office_value.description:
Checks the planet's branch officevalue
branch_office_value = { who = <target> value > 10/variable }
Supported Scopes: planet ship colony

can_set_policy.description:
Checks if the country is allowed to set its policy to a specific one using set_policy effect
can_set_policy = { policy = <key> option = <key> }
Supported Scopes: country

num_buildings.description:
Checks the number the scoped object has of any, or a specific, building
num_buildings = {  type = <key/any>  value > 2/variable  disabled = <any(default)/yes(only)/no(only)>  in_construction = <any/no(default)/yes(only)>  category = <any(default)/for example unity or resource> owner_type = <normal/corporate/subject_holding> limit = {} (scope = colony) }
Supported Scopes: planet country ship galactic_object colony

num_districts.description:
Checks the number the colony has of any, or a specific, district
num_districts = { type = <key/any> value > 2/variable }
Supported Scopes: planet country ship colony

num_free_districts.description:
Checks the number of available slots the colony has of any, or a specific, district
num_free_districts = { type = <key/any> value > 2/variable }
Supported Scopes: planet ship colony

has_attitude_behavior.description:
Checks if the country has the specified AI behavior towards another country 
has_attitude_behavior = {
	target = <country>
	behavior = attack/weaken/vassalize/alliance/coexist/trade
}
Supported Scopes: country

their_opinion.description:
Checks target country's opinion value of the current country
their_opinion = { who = <target> value > 25/variable }
Supported Scopes: country

is_surveyed.description:
Checks if the scoped object has been surveyed by target country
is_surveyed = { who = <target> status = yes }
Supported Scopes: planet ship galactic_object astral_rift colony

check_variable.description:
Checks a variable for the country/leader/planet/system/fleet
check_variable = { which = <variable> value >=< <float>/<variable>/<scope.variable>/trigger:<trigger> }
Supported Scopes: megastructure planet country ship pop pop_group fleet galactic_object leader army ambient_object species bypass pop_faction war federation starbase deposit sector archaeological_site first_contact spy_network espionage_operation espionage_asset agreement situation astral_rift ship_growth_stage colony

habitability.description:
Checks the planet's habitability (0 to 1) for target pop group/species
habitability = { who = <target> value = 0.6 }
Supported Scopes: planet ship colony

has_holding.description:
Checks if the planet has any, or a specific, holding
has_holding = { holding = any/none/<holding> owner = <owner> }
Supported Scopes: planet ship colony

has_envoy_task.description:
Checks the scoped leader's diplomatic/envoy task.
has_envoy_task = {
	task = improve_relations/harm_relations/federation/galactic_community/spy_network/first_contact/strengthen_imperial_authority/undermine_imperial_authority/none
	target = <country> (optional)
}
Supported Scopes: leader

has_opinion_modifier.description:
Checks if the country has a specific opinion modifier towards target country or anyone
has_opinion_modifier = { who = <target (optional)> modifier = encroaching_colony is_reverse = no }
Supported Scopes: country

has_completed_event_chain_counter.description:
Checks if the country has completed a specific counter in an event chain
has_completed_event_chain_counter = { event_chain = amoebas_2_chain counter = amoebas_slaughtered }
Supported Scopes: country

has_relation_flag.description:
Checks if the country has a relation flag towards target country
has_relation_flag = {
	who = <target>
	flag = <flag> (note: one can use e.g. my_flag@from to track relationships between objects)
}
Supported Scopes: country

reverse_has_relation_flag.description:
Checks if the target country has a relation flag towards the country
reverse_has_relation_flag = {
	who = <target>
	flag = <flag> (note: one can use e.g. my_flag@from to track relationships between objects)
}
Supported Scopes: country

is_ideal_planet_class.description:
Checks if the planet is of the ideal class for target country, species or pop
is_ideal_planet_class = { who = <target> status = yes/no }
Supported Scopes: planet ship colony

intel_level.description:
Checks the country's intel level of target system
intel_level = { level > low system = <target> }
Supported Scopes: country

can_declare_war.description:
Checks if the country can declare war against target country
can_declare_war = {
	target = <target country>
	attacker_war_goal = <war goal>
}
Supported Scopes: country

has_country_resource.description:
Checks the country's amount of a specific stored resource
has_country_resource = { type = minerals amount > 99/variable }
Supported Scopes: country

num_killed_ships.description:
Checks how many of target country's ships that the country has destroyed
num_killed_ships = { target = <target> value > 5/variable }
Supported Scopes: country

num_taken_planets.description:
Checks how many planets the country has taken from target country
num_taken_planets = { target = <target> value > 1 }
Supported Scopes: country

opposing_ethics_divergence.description:
Checks the divergence between the scoped and the target countries' ethos
opposing_ethics_divergence = {
	steps > <variable>
	who = <target>
}
Supported Scopes: country

has_monthly_income.description:
Checks the country's monthly income of a specific resource
has_monthly_income = { resource = engineering_research  value < 20 }
Supported Scopes: country

else.description:
Evaluates the triggers if the display_triggers of preceding 'if' or 'else_if' is not met
if = { limit = { <display_triggers> } <triggers> }
 else = { <triggers> }
Supported Scopes: all

count_deposits.description:
Checks the number of deposits on the colony carrier that meet the specified criteria
count_deposits = { type = <deposit> category = <category> count < 2 }
Supported Scopes: planet ship colony

count_species_traits.description:
Checks the number of unique traits within the set parameters on a species or pop group
count_species_traits = { limit = {} category = <category> cost < = > <trait cost> | count < 2 }
Supported Scopes: pop pop_group species

count_tech_options.description:
Checks the country's number available tech research options in a specific field
count_tech_options = { area = physics count > 0/variable }
Supported Scopes: country

has_point_of_interest.description:
Checks if the scoped country has a specific point of interest in its situation log
has_point_of_interest = { poi = <id> }
Supported Scopes: planet country ship fleet galactic_object ambient_object

compare_distance.description:
Checks whether the current scope is closer to a specified object than it is to a second specified object within the same solar system.
compare_distance = { closer_object = root further_object = from }
Supported Scopes: megastructure planet ship pop pop_group fleet galactic_object leader ambient_object starbase deposit archaeological_site first_contact colony

custom_tooltip_fail.description:
Shows custom text only when the associated trigger fails
custom_tooltip_fail = {
	text = <text>
	<triggers>
}
Supported Scopes: all

hidden_progress.description:
Nullifies progress of triggers inside it and returns progress '0 of 0'
hidden_progress = {
	<triggers>
}
Supported Scopes: all

simple_progress.description:
Hides the progress of the triggers inside and returns progresses '0 of 1' or '1 of 1'
simple_progress = {
	<triggers>
}
Supported Scopes: all

is_war_participant.description:
Checks if target country is participating in the war on the specified side
is_war_participant = { who = <target>/war = <target> side = attackers/defenders/<target> }
Supported Scopes: country war

would_join_war.description:
Checks if the country would join the side of target country in a hypothetical war
would_join_war = { attacker = <target> defender = <target> side = <target> }
Supported Scopes: country

years_of_peace.description:
Checks the number of in-game years country has been at peace, with optional parameter to delay from start of game
years_of_peace = { value > 10/variable delay = 0 }
Supported Scopes: country

count_starbase_modules.description:
Checks the number of starbase modules that are of the specified type or not
count_starbase_modules = { type = anchorage (optional) include_being_constructed = yes/no count < 12/variable }
Supported Scopes: country galactic_object starbase

count_starbase_buildings.description:
Checks the number of starbase buildings that are of the specified type or not
count_starbase_buildings = { type = command_center (optional) include_being_constructed = yes/no count < 12/variable }
Supported Scopes: country galactic_object starbase

can_research_tier.description:
Checks whether the country can research a certain tech tier
can_research_tier = { tier = 1 area = society }
Supported Scopes: country

war_begun_num_fleets_gone_mia.description:
Checks amount of target country's fleets that went MIA when the war began
war_begun_num_fleets_gone_mia = { who = <target> value < 10 }
Supported Scopes: war

custom_tooltip_success.description:
Shows custom text only when the associated trigger passes
custom_tooltip_success = {
	text = <text>
	<triggers>
}
Supported Scopes: all

success_text.description:
For 'desc={trigger={' use. Shows custom text when the associated trigger passes.
success_text = {
	text = <text>
	<triggers>
}
Supported Scopes: all

fail_text.description:
For 'desc={trigger={' use. Shows custom text when the associated trigger fails.
fail_text = {
	text = <text>
	<triggers>
}
Supported Scopes: all

calc_true_if.description:
Returns true if the specified number of sub-triggers return true
calc_true_if = { amount = 2/variable <trigger> <trigger> <trigger> }
Supported Scopes: all

num_pops_assigned_to_job.description:
Checks the number of pops assigned to the job (in total or from a specific pop group)
num_pops_assigned_to_job = {
	pop_group = <target> (if not specified, check total number)
	value < 300
}
Supported Scopes: pop job

resource_income_compare.description:
Checks specific resource income value for the country scope (note: checks profit minus loss, not revenue):
resource_income_compare = {
	resource = <resource_name>
	value ><= <value>
}
Supported Scopes: country

pop_amount_percentage.description:
Checks the percentage of pops in the scope that fulfill the specified criteria
pop_amount_percentage = {
	percentage > 0.74/variable
	limit = { <triggers> }
	exclude = { <triggers> } (optional: specifies pop groups to exclude from the calculation)
}
Supported Scopes: planet country ship pop_faction sector colony

pop_ethic_amount.description:
Checks the amount or percentage of pops following or not following the ethic. If used rhs this return amount of pops.
pop_ethic_amount = {
	amount ><= <value>/<variable> OR percentage ><= <value>/<variable>
	ethic = <key> OR ethic != <key>
}
Supported Scopes: country pop_group pop_faction colony

pop_ethic_percentage.description:
Checks the amount or percentage of pops following or not following the ethic. If used rhs this return percentage of pops.
pop_ethic_percentage = {
	amount ><= <value>/<variable> OR percentage ><= <value>/<variable>
	ethic = <key> OR ethic != <key>
}
Supported Scopes: country pop_group pop_faction colony

is_job_of_pop_category.description:
Checks if a job is of a certain pop category. Note that the result for this trigger is not dependent on where it is used - so it's for use in e.g. templated script values.
is_job_of_pop_category = { job = <job> category = <category> }
Supported Scopes: all

has_citizenship_type.description:
Checks if a species/pop group/leader has a particular citizenship type in their country
has_citizenship_type = { country = <who> type = <type> }
Supported Scopes: pop pop_group leader species

has_population_control.description:
Checks if the pop group is prevented from reproducing
has_population_control = { type = bool/<type> country = scope }
Supported Scopes: pop pop_group leader species

has_migration_control.description:
Checks if the pop group is prevented from migrating
has_migration_control = { type = bool/<type> country = scope }
Supported Scopes: pop pop_group leader species

has_military_service_type.description:
Checks if a species/pop group/leader has a particular military service type in their country
has_military_service_type = { country = <who> type = <type> }
Supported Scopes: pop pop_group leader species

has_purge_type.description:
Checks if a species/pop group/leader has a particular purge type in their country
has_purge_type = { country = <who> type = <type> }
Supported Scopes: pop pop_group leader species

has_slavery_type.description:
Checks if a species/pop group/leader has a particular slavery type in their country
has_slavery_type = { country = <who> type = <type> }
Supported Scopes: pop pop_group leader species

has_living_standard.description:
Checks if a species/pop group/leader has a particular living standard in their country
has_living_standard = { country = <who> type = <type> }
Supported Scopes: pop pop_group leader species

has_colonization_control.description:
Checks if the pop group is prevented from colonizing
has_colonization_control = { type = bool/<type> country = scope }
Supported Scopes: pop pop_group leader species

count_species.description:
Counts the number of species in the scope that fulfill the specified criteria, not counting sub-species as unique.
count_species = { count > 4 limit = { <triggers> } }
Supported Scopes: planet country ship colony

count_exact_species.description:
Counts the number of species in the scope that fulfill the specified criteria, counting sub-species as unique.
count_exact_species = { count > 4 limit = { <triggers> } }
Supported Scopes: planet country ship colony

pop_maintenance_cost.description:
Checks the maintenance costs of a pop group
pop_maintenance_cost = { value > 0.5/variable resource = energy }
Supported Scopes: pop_group

has_casus_belli.description:
Checks if the country has a valid casus belli (any casus belli or a specific one) on the given country.
 has_casus_belli = { 
	target = <country> 
	type = <cb_type> #optional
 }
Supported Scopes: country

using_war_goal.description:
Checks if a war has a specific war goal
using_war_goal = { type = <war goal> owner = <eventtarget, country> }
Supported Scopes: war

count_starbase_sizes.description:
Checks if the scoped country has a specified quantity of a starbase size
count_starbase_sizes = {
	starbase_size = <starbase_ship_size> 
	count >= 2/variable
}
Supported Scopes: country

inverted_switch.description:
Switch case for a trigger treated as NOT.
inverted_switch = {
	trigger = has_ethic
	ethic_xenophile = { <trigger> }
	ethic_xenophobe = { <trigger> }
	default = { <trigger> }
}
Supported Scopes: all

federation_experience.description:
Checks experience of the federation.
federation_experience >=< 40 );
Supported Scopes: federation

federation_cohesion.description:
Checks cohesion of the federation.
federation_cohesion >=< 40 );
Supported Scopes: federation

federation_cohesion_growth.description:
Checks cohesion growth of the federation.
federation_cohesion_growth >=< 40 );
Supported Scopes: federation

has_passed_resolution.description:
Checks if country has passed a Galactic Community resolution in last x days/months/years
has_passed_resolution = { days/months/years = <int32> }
Supported Scopes: country

num_assigned_jobs.description:
Checks the number of pops the colony or country has that work a specific job.
num_assigned_jobs = { job = <key> value > 201 }
Supported Scopes: planet country ship galactic_object colony

relative_encryption_decryption.description:
Divides the encryption value of the scope object with the decryption value of the target and compares with value. Target is only used for country scope.
relative_encryption_decryption = {
	target = <country>
	value > 1.0/variable
}
Supported Scopes: country spy_network espionage_operation

has_term_value.description:
Checks if the agreement has a specific term
has_term_value = { term = <term> value = <term_value> }
Supported Scopes: agreement

is_action_active.description:
Check if a trade action is already active in a trade deal with the specified empire (or with any empire if so specified)
is_action_active = { action = <action_key> with_country = <other_country_scope/any> }
Supported Scopes: country

can_afford_special_offer.description:
Checks if the scoped country can afford the offer given by the target country. Only works in certain parts of the script marked with ai_trade_facility.
can_afford_special_offer = { target = <country> } 
Supported Scopes: country

count_used_naval_cap.description:
Checks used naval cap by the scoped country or fleet's controlled ships which fulfill the specified criteria.
count_used_naval_cap = { limit = { <triggers> } count < 6 }
Supported Scopes: country ship fleet

has_dna.description:
Check if dna has been acquired for the given category
has_dna = { ship_category = <key> rarity=<key> (optional) }
Supported Scopes: country

trait_has_all_tags.description:
Checks if a trait has all tags in the list 
trait_has_all_tags = { biological lithoids }
Supported Scopes: trait

trait_has_any_tag.description:
Checks if a trait has at least one tag from the list 
trait_has_any_tag = { biological lithoids }
Supported Scopes: trait

has_patron_relation.description:
Check if the scoped country has established a relation with given patron. The contact state can be specified (completed by default).
has_patron_relation = {
	patron = <patron_key / any>
	contact (optional) = <completed (default)/in_progress/none/any>
}
Supported Scopes: country

planet_happiness_above_threshold.description:
Checks if a planet's happiness is past a given threshold. Can be used in a scoped system, then it returns the sum of every planets' happiness past the given threshold. In system scope an optional limit (colony scope) filters which colonies contribute.
planet_happiness_above_threshold = { threshold = 0.5 limit = { is_owned_by = root } value > 0 }
Supported Scopes: planet galactic_object

num_neighbor_systems.description:
Checks the number of neighbor systems within a specific distance
num_neighbor_systems = {
	max_distance = 1
	limit = <triggers>
}
Supported Scopes: all

num_zones.description:
Checks the number the colony has of any, or a specific, zone
num_zones = { type = <key/any> value > 2/variable }
Supported Scopes: planet country ship colony

total_workforce_with_job_tag.description:
Checks how much workforce that has jobs with all given tags in a planet
total_workforce_with_job_tag = { tags = { farmer trader } value = 1000 }
Supported Scopes: planet ship colony

total_system_workforce_with_job_tag.description:
Checks how much workforce that has jobs with all given tags in a system. An optional limit (colony scope) filters which colonies contribute.
total_system_workforce_with_job_tag = { tags = { farmer trader } limit = { is_owned_by = root } value = 1000 }
Supported Scopes: galactic_object

total_country_workforce_with_job_tag.description:
Checks how much workforce that has jobs with all given tags in a country
total_country_workforce_with_job_tag = { tags = { farmer trader } value = 1000 }
Supported Scopes: country

nb_pop_exact_species.description:
Checks the amount of pops in the planet that have the exact species.
nb_pop_exact_species = {
	species = <target>
	value = 1/variable
}
Supported Scopes: planet ship colony

count_ship_size_in_system.description:
Checks the sum of the ship_size's size_multiplier of every ship present in the scoped system.
Checks whether the enclosed triggers return true for X/all of them
count_ship_size_in_system = {
	count = <num/all/variable>
	limit = { <triggers> }
}
Supported Scopes: galactic_object

num_claims_on_system.description:
Counts the number of claims the scoped empire has on the target system
num_claims_on_system = { Target = FROM Count >= 1 }
Supported Scopes: country

any_agreement.description:
Iterate through each agreement - checks whether the enclosed triggers return true for any of them
any_agreement = { <triggers> }
Supported Scopes: country no_scope

count_agreement.description:
Iterate through each agreement - checks whether the enclosed triggers return true for X/all of them
count_agreement = {
	count = <num/all/variable>
	limit = { <triggers> }
}
Supported Scopes: country no_scope

any_ambient_object.description:
Iterate through every ambient object in the game - checks whether the enclosed triggers return true for any of them
any_ambient_object = { <triggers> }
Supported Scopes: all

count_ambient_object.description:
Iterate through every ambient object in the game - checks whether the enclosed triggers return true for X/all of them
count_ambient_object = {
	count = <num/all/variable>
	limit = { <triggers> }
}
Supported Scopes: all

any_system_ambient_object.description:
Iterate through every ambient object in the solar system - checks whether the enclosed triggers return true for any of them
any_system_ambient_object = { <triggers> }
Supported Scopes: galactic_object

count_system_ambient_object.description:
Iterate through every ambient object in the solar system - checks whether the enclosed triggers return true for X/all of them
count_system_ambient_object = {
	count = <num/all/variable>
	limit = { <triggers> }
}
Supported Scopes: galactic_object

any_archaeological_site.description:
Iterate through every archaeological sites - checks whether the enclosed triggers return true for any of them
any_archaeological_site = { <triggers> }
Supported Scopes: all

count_archaeological_site.description:
Iterate through every archaeological sites - checks whether the enclosed triggers return true for X/all of them
count_archaeological_site = {
	count = <num/all/variable>
	limit = { <triggers> }
}
Supported Scopes: all

any_owned_army.description:
Iterate through each army that is owned by the country - checks whether the enclosed triggers return true for any of them
any_owned_army = { <triggers> }
Supported Scopes: country

count_owned_army.description:
Iterate through each army that is owned by the country - checks whether the enclosed triggers return true for X/all of them
count_owned_army = {
	count = <num/all/variable>
	limit = { <triggers> }
}
Supported Scopes: country

any_planet_army.description:
Iterate through each army on the colony (not in ground combat), regardless of owner. - checks whether the enclosed triggers return true for any of them
any_planet_army = { <triggers> }
