hidden_effect.description:
Prevents enclosed effects from being displayed in tooltip
hidden_effect = { <effects> }
Supported Scopes: all

if.description:
Executes enclosed effects if limit criteria are met
if = { limit = { <triggers> } <effects> }
Supported Scopes: all

random_list.description:
Picks one random set of effects from a list, influenced by relative weight
random_list = { 50 = { <effects> } 20 = { <effects> } 30 = { <effects> } 999 = { <effects> } }
Supported Scopes: all

locked_random_list.description:
Picks one random set of effects from a list, influenced by relative weight once per event scope
locked_random_list = { 50 = { <effects> } 20 = { <effects> } 30 = { <effects> } 999 = { <effects> } }
Supported Scopes: all

add_blocker.description:
Adds a blocker to a colony carrier, with some control over what it is set to block (add_deposit will add a random planetary deposit to block)
add_blocker = {
	type = <key>
	blocked_deposit = none (default)/<deposit scope - copies the type to the blocked deposit but any flags or variables are lost>/random
}
Supported Scopes: planet ship colony

remove_holding.description:
Removes a specific holding from the scoped planet
remove_holding = { holding = <key> owner = <owner> }
Supported Scopes: planet ship colony

add_holding.description:
Adds a specific holding on the scoped colony
add_holding = { holding = <key> owner = <owner> }
Supported Scopes: planet ship colony

give_technology.description:
Instantly gives a specific tech to the scoped country
give_technology = { tech = tech_desert_colonization message = yes }
Supported Scopes: country

set_faction_properties.description:
Sets country's faction properties:
set_faction_properties = { some_flag_1 = yes some_flag_2 = no }
Supported Scopes: country

create_fleet.description:
Creates a new fleet
create_fleet = { name = <string> effect = { <create_ship, set_owner, set_location etc effects go here> } } 
Supported Scopes: all

create_random_fleet.description:
Creates a fleet of the requested size by repeatedly picking ships from the listed designs at random, weighted by each entry's weight (default 1). Each entry may also specify a guaranteed min count and a max cap. If ship_designs is omitted, falls back to the country's own AI-recruitable designs at uniform weight.
create_random_fleet = {
	name = <string>
	size = <int>
	can_overflow = yes/no # default yes
	ship_designs = { # optional; if omitted, uses the country's own designs at uniform weight
		NAME_a # bare name, weight 1, no min/max
		{ design = NAME_b weight = 2.4 min = 1 max = 3 }
	}
	effect = { <set_location etc effects go here> }
}
Supported Scopes: country

create_mining_station.description:
Creates a mining station in orbit of the scoped planet or astral rift
create_mining_station = { owner = <target> }
Supported Scopes: planet astral_rift

create_research_station.description:
Creates a research station in orbit of the scoped planet or astral rift
create_research_station = { owner = <target> }
Supported Scopes: planet astral_rift

set_surveyed.description:
Sets the colony carrier/astral rift or system as un/surveyed by target country
set_surveyed = { surveyed = yes surveyor = <target> }
Supported Scopes: planet ship galactic_object astral_rift

export_modifier_to_variable.description:
Exports the value of a specified modifier in the current scope to a specified variable.
export_modifier_to_variable = { modifier = logistic_growth_mult variable = <string> }
Supported Scopes: megastructure planet country ship pop pop_group fleet galactic_object leader army species pop_faction colony

export_modifier_duration_to_variable.description:
Exports the remaining duration of a specified modifier in the current scope to a specified variable.
export_modifier_duration_to_variable = { modifier = modifier_name variable = <string> }
Supported Scopes: planet country pop pop_group fleet

export_trigger_value_to_variable.description:
Exports the value of a trigger to a specified variable (so for num_pops, it'll export the number of pops).
export_trigger_value_to_variable = {
	trigger = has_resource
	parameters = { resource = energy } (optional: specify extra parameters for triggers with { }
	variable = <string> (this example will print the amount of energy the scoped object has to a variable)
	rounded = yes (default: no)
}
Supported Scopes: megastructure planet country ship pop pop_group fleet galactic_object leader army ambient_object species bypass pop_faction war federation starbase deposit sector archaeological_site first_contact spy_network espionage_operation espionage_asset agreement situation astral_rift ship_growth_stage colony

export_resource_stockpile_to_variable.description:
Exports the value of the current country's stockpile of the specified resource to a variable.
export_resource_stockpile_to_variable = { resource = energy variable = <string> }
Supported Scopes: country

export_resource_income_to_variable.description:
Exports the value of the current country's monthly income of the specified resource to a variable.
export_resource_income_to_variable = { resource = energy variable = <string> }
Supported Scopes: country

export_resource_maximum_to_variable.description:
Exports the value of the current country's maximum of the specified resource to a variable.
export_resource_maximum_to_variable = { resource = energy variable = <string> }
Supported Scopes: country

set_variable_to_random_value.description:
Sets a variable to a random value within the specified bounds.
set_variable_to_random_value = { which = <some_variable> min = -100 max = 100 rounded = yes/no }
Supported Scopes: megastructure planet country ship pop pop_group fleet galactic_object leader army ambient_object species bypass pop_faction war federation starbase deposit sector archaeological_site first_contact spy_network espionage_operation espionage_asset agreement situation astral_rift ship_growth_stage colony

change_variable.description:
Increments a previously-set variable by a specific amount
change_variable = { which = <string> value = <float>/<variable>/<scope.variable>/trigger:<trigger> }
Supported Scopes: megastructure planet country ship pop pop_group fleet galactic_object leader army ambient_object species bypass pop_faction war federation starbase deposit sector archaeological_site first_contact spy_network espionage_operation espionage_asset agreement situation astral_rift ship_growth_stage colony

spawn_system.description:
Spawns a new system at a position relative to the scoped object.
spawn_system = { min_jumps = <value> max_jumps = <value> min_distance = <int 0-100> max_distance = <int 0-100> initializer = <key for pre-defined system>/random hyperlane=<yes/no> is_discovered=<yes/no>}
Supported Scopes: megastructure planet ship fleet galactic_object starbase no_scope colony

create_nebula.description:
Creates a new Nebula with a given radius centered around the current system.
create_nebula = {
	name = <name> (loc synced, optional - default is random)
	radius = 100
	effect = { <effects on every system in the new nebula> }
}
Supported Scopes: galactic_object

begin_event_chain.description:
Starts a situation log event chain for target country
begin_event_chain = { event_chain = <key> target = <target> }
Supported Scopes: all

queue_actions.description:
Adds actions to the scoped fleet's action queue
queue_actions = { repeat = { <fleet actions> } }
Supported Scopes: fleet

create_ambient_object.description:
Creates a new ambient object
create_ambient_object = { type = <key> location = <target> }
For VFX use:
create_ambient_object = {
	type = <key>
	scale = <float>
	location = <target>
	use_3d_location = <bool, use 3D entity or 2D coordinate of the location entity as base>
	entity_offset = {
		min = <int>
		max = <int>
	}
	entity_offset_angle = {
		min = <int>
		max = <int>
	}
	entity_offset_height = {
		min = <int>
		max = <int>
	}
