	owner = <target>
	size = <ship_size>
	design=<starbase global design>s
	module = <starbase_module>
	building = <starbase_building>
	effect = { ... }
}
Supported Scopes: planet galactic_object

set_starbase_module.description:
Sets a module in a slot on a starbase
set_starbase_module = { slot = <int> module = <starbase_module> }
Supported Scopes: starbase

set_starbase_building.description:
Sets a building in a slot on a starbase
set_starbase_building = { slot = <int> building = <starbase_building> }
Supported Scopes: starbase

remove_starbase_module.description:
Removes a module from a certain slot or all slots on a starbase
remove_starbase_module = { slot = <int> (optional, default = all) module = <starbase_module> (optional) }
Supported Scopes: starbase

remove_starbase_building.description:
Remove a building from a certain slot or all slots on a starbase
remove_starbase_building = { slot = <int> (optional, default = all) building = <starbase_building> (optional) }
Supported Scopes: starbase

add_casus_belli.description:
Adds a Casus Belli to the scoped country against the target country.
add_casus_belli = { type = cb_subjugation who = <country> days = 10/variable }
Supported Scopes: country

effect_on_blob.description:
Executes an effect on systems with colonies owned by the scoped country, starting at an origin, and until a certain percentage of owned colonies matching the planet_limit has been covered.
effect_on_blob = {
	center = <system target>
	owned_planets_percentage = 1.0/variable
	planet_limit = { <colony triggers> }
	effect = { <system effects> }
}
Supported Scopes: country

check_casus_belli_valid.description:
Re-evaluate the specified casus belli type with given target country
check_casus_belli_valid = {
	target = none/<optional country target>
	type = <optional casus belli type>
}
Supported Scopes: country

clone_leader.description:
Clones the last created leader for the scoped country
clone_leader = {
	target = <event target>
	#Properties to override, see create_leader
	#traits is only overridden if the override is not empty
	#randomize_traits is only used if traits is overridden
	#If traits is not overridden, trait picks are also copied
	effect = { ... }
}
Supported Scopes: country

add_hyperlane.description:
Adds a hyperlane between two systems
add_hyperlane = { from = <system> to = <system> }
Supported Scopes: all

remove_hyperlane.description:
Removes existing hyperlane between two systems
remove_hyperlane = { from = <system> to = <system> }
Supported Scopes: all

else_if.description:
Executes enclosed effects if limit criteria of preceding 'if' or 'else_if' is not met, and its own limit is met
if = { limit = { <triggers> } <effects> }
else_if = { limit = { <triggers> } <effects> }
Supported Scopes: all

create_saved_leader.description:
Creates a new saved leader for the scoped country with a lookup key. See create_leader for parameters.
create_saved_leader = {  }
Supported Scopes: country

activate_saved_leader.description:
Moves a saved leader to the active for the scoped country with a lookup key
activate_saved_leader = {
	key = <string>
	add_to_owned=<yes/no> #default yes
	effect = {...}
}
Supported Scopes: country

add_asteroid_belt.description:
Adds an asteroid belt at the distance in the scope.
