Supported Scopes: country

set_diplomacy_action_setting.description:
Sets diplomatic action custom setting. Please don't use outside law on_enact, functional effect! Use set_federation_law and has_federation_law instead.
set_diplomacy_action_setting = {
	action = <action_key>
	settings = { vote_type = default }
}
Supported Scopes: federation

set_federation_settings.description:
Sets diplomatic action custom setting. Please don't use outside law on_enact, functional effect! Use set_federation_law and has_federation_law instead.
set_federation_settings = {
	<setting> = <value>
	...
}
Supported Scopes: federation

add_associate_member.description:
Add specified country as an associate member
add_associate_member = { who = <target> override_requirements = yes/no }
Supported Scopes: federation

remove_associate_member.description:
Removes a specific associate member from the federation
remove_associate_member = { who = <country> override_requirements = yes/no }
Supported Scopes: federation

complete_special_project.description:
Completes a specific special project for the country, firing the on complete effects
complete_special_project = { type = <project key> location = <target> }
Supported Scopes: country

add_intel.description:
Adds the defined amount of intel toward the target empire
add_intel = { amount = <float>/<variable> who = <target> }
Supported Scopes: country

fire_on_action.description:
Fires a made-up on_action.
fire_on_action = { on_action = <string> scopes = { from = X fromfrom = Y } }
Supported Scopes: all

create_espionage_asset.description:
Creates espionage asset within a given spy network
create_espionage_asset = {
	type = <espionage asset type>
	effect = { <effects executed on asset> }
}
Supported Scopes: spy_network

start_situation.description:
Begins a situations.
start_situation = { type = <situation_type> target = <scope> }
Supported Scopes: country

join_war_on_side.description:
Joins the war on the specified side.
join_war_on_side = { war = <target> side = attackers/defenders/<country> }
Supported Scopes: country

remove_random_starbase_building.description:
Remove a number of random building(s) matching/not matching a type from the starbase
remove_random_starbase_building = {
	type = <starbase building> ( optional. default: all )
	count = <int> (optional. default: 1 )
}
Supported Scopes: starbase

remove_random_starbase_module.description:
Remove a number of random module(s) matching/not matching a type from the starbase
remove_random_starbase_module = {
	type = <starbase module> ( optional. default: all )
	count = <int> (optional. default: 1 )
}
Supported Scopes: starbase

set_timed_espionage_operation_flag.description:
Sets an arbitrarily-named flag on the scoped espionage operation for a set duration
set_timed_espionage_operation_flag = {
	flag = <key> (note: one can use <key>@scope e.g. my_flag@from to track relationships between objects)
	days/months/years = <int>/<variable>
}
Supported Scopes: espionage_operation

add_victory_score.description:
Adds victory score to a country
add_victory_score = { source=<loc_key> score=<value>/<variable> }
Supported Scopes: country

pass_debris_ownership.description:
Passes the scoped debris ownership to the specified country 
pass_debris_ownership = { owner = <target country> }
Supported Scopes: debris

set_ship_design.description:
Changes which design a ship uses/all ships in a fleet use, to the target design
set_ship_design = {
  design = <ship design key/target/last_created_design, or use random_existing_design>
  random_existing_design = <ship size key>
}
Supported Scopes: ship fleet

lock_bypass.description:
Lock a Bypass for exclusive access for a given country.
lock_bypass = { country = owner duration = 360 }
Supported Scopes: bypass

give_specimen.description:
Gives a given specimen to the target country.
give_specimen = { key = <specimen> origin = <key> }
Supported Scopes: country

storm_apply_aftermath_modifier.description:
Applies Cosmic Storm Aftermath Modifiers. You can specify up to a max of 10 Severities and each one will be chosen based on it's chance.
storm_apply_aftermath_modifier = { severity = { modifier = <key>, days = <ModifierDuration> chance = <WeightedChance> effect  = <OnAppliedOptionalEffect> }}
Supported Scopes: all

set_mission_counter.description:
Sets a mission counter for the scoped country to a specific amount
set_mission_counter = { mission = <key> counter = <key> amount = <int>/<variable> }
Supported Scopes: country

stop_mission.description:
Stops the mission with the given status, triggering the relevant effects.
 stop_mission = { mission = <mission_key> status = success }
Supported Scopes: country

give_culling_rewards.description:
Gives associated culling rewards from a space fauna design to the target country.
give_culling_rewards = {
	design = <key>
	mult = <value> (optional, default: 1)
}
Supported Scopes: country

give_dna.description:
Gives given space fauna DNA with given rarity to the target country.
give_dna = { ship_category = <key> rarity = <key> (optional) }
Supported Scopes: country

add_to_vivarium.description:
Gives Space Fauna in the Vivarium using given ship design with given rarity to the target country.
add_to_vivarium = { design = <key> rarity = <key>/highest (optional) amount = <int> (optional) }
Supported Scopes: country

reanimate_space_fauna.description:
Reanimates Space Fauna ship(s) back to life in zombie form.
reanimate_space_fauna = {
	fleet = <fleet>
}
Supported Scopes: ship debris

replace_patron.description:
Replace a patron with another one, creating the patron relation if it does not yet exist, and setting the new patron to the replaced patron's position in the shroud plane.
replace_patron = { new_patron = <patron_key> replaced_patron = <patron_key> }
Supported Scopes: country

add_attunement.description:
Adds attunement towards specified patron(s).
This effect can be displayed if necessary, but you'll need to place it at the end of all displayed effects.
The displayed text will depend on the contactstate with the patron(s).
add_attunement = {
	<patron 1> = <value 1>
	<patron 2> = <value 2>
	<...>
	}
}
Supported Scopes: country

set_attunement.description:
Sets attunement of the specified patron to a specific amount.
set_attunement = { value = <value> patron = <patron> }
Supported Scopes: country

steal_specimens.description:
Steals random specimens from given country.
steal_specimens = { who = <country> category = <category_key>/all/any count = <int>show_nofication = <yes/no> }
Supported Scopes: country

enable_patron_first_contact_project.description:
Enables a specific special research project for the target country at a specific location (should be the same as the current scope where possible). This special project will be the one used for the Patron First Contact. The relation contact state will be set to In Progress if needed.
enable_patron_first_contact_project = {
	name = <project key>
	patron = <patron key>
	owner = <target, default = root> location = <target, ideally THIS (that is default)> }
Supported Scopes: country

copy_traditions_from.description:
Copies the traditions of the target country into the scoped country. Traditions are added to the existing traditions, and the potential/possible triggers are respected.the traditions listed in the exceptions list are not copied.
copy_traditions_from = {
    target = FROM
    exceptions = { tradition1 tradition2 }
}
Supported Scopes: country

copy_ascension_perks_from.description:
Copies the Ascension Perks of the target country into the scoped country. Perks are added to the existing perks, and the potential/possible triggers are respected.the perkss listed in the exceptions list are not copied.
copy_ascension_perks_from = {
    target = FROM
    exceptions = { perk1 perk2 }
}
Supported Scopes: country

add_focus_progress.description:
Adds the defined amount of focus progress in the defined focus category
add_focus_progress = { category = <focus_category_key> amount = <float>/<variable> }
Supported Scopes: country

set_habitability_trait.description:
Set planet preference trait for scoped species (removing the current one, if any).
set_habitability_trait = { trait = <trait> }
Supported Scopes: species

reset_growth.description:
Resets growth to zero (non-fauna ships)
reset_growth = {}
Supported Scopes: ship fleet

sacrifice_pop_group.description:
Instantly destroys part of a pop group (prefer to use instead of kill_pop_group when the country intentionally kills it)
sacrifice_pop_group = { pop_group = <target pop group> amount = <amount killed> OR percentage = <percentage killed> }
Supported Scopes: all

sacrifice_assigned_pop_amount.description:
Instantly sacrifices part of the assigned pops to this job
sacrifice_assigned_pop_amount = {
	limit = { <triggers> }
	amount = <amount sacrificed> OR percentage = <percentage sacrificed>
}
Supported Scopes: pop job

kill_assigned_pop_amount.description:
Instantly destroys part of the assigned pops to this job
kill_assigned_pop_amount = {
	limit = { <triggers> }
	amount = <amount killed> OR percentage = <percentage killed>
	random = <number> (optional)
	growth_category = <key> (optional, default: 'GROWTH_CAT_OTHER')
}
Supported Scopes: pop job

set_patron_first_contact_state.description:
Sets the contact state with a Shroud Patron (will create the relation if needed).
set_patron_first_contact_state = {
	patron = <patron_name>
	state = <none / in_progress / completed (default)>
}
Supported Scopes: country

transfer_resource_stockpile.description:
Transfers all resources from the scoped ship to another ship or country:
transfer_resource_stockpile = {
	target = <ship/country scope> (Must be able to collect resources; will not add resources above capacity)
	mult = <variable> (optional: multiplies all transferred resources by a variable if this is less than 1, all resources are removed from the ship but the target only receives a fraction, e.g.mult = 0.5 would give the target 50 % of the ship's stockpile with the remainder disappearing)
}
Supported Scopes: ship

transfer_resources_to_empire.description:
Transfers the scoped country's stockpile of each listed resource to another country:
transfer_resources_to_empire = {
	target = <country scope>
	resources = { minerals energy ... }
	percentage = 0.5/variable (optional: share of each stockpile to transfer, clamped to [0, 1]; default 1.0. Any amount above the target's storage capacity is lost, with the remainder disappearing)
}
Supported Scopes: country

reset_event_chain_counter.description:
Resets n event chain counter for the scoped country
reset_event_chain_counter = { event_chain = <key> counter = <key> }
Supported Scopes: country

random.description:
All enclosed effects may or may not be executed depending on set chance
random = { chance = 50 <effects> }
Supported Scopes: all

create_ship_design.description:
Creates a new ship design for use with last_created_design target
create_ship_design = { design = <key> ftl = <target, optional, sets FTL drive to target country's> }
Supported Scopes: all

change_government.description:
Change the scoped country's government authority and/or civics
change_government = random
or
change_government = {
	authority = random / <key>
	civics = random / { civic = <key> civic = random }
cooldown = no (default: yes)
remove_invalid_civics = yes (default: no)
}
Supported Scopes: country

enable_special_project.description:
Enables a specific special research project for target country at a specific location (should be same as the current scope where possible)
enable_special_project = { name = <project key> owner = <target, default = root> location = <target, ideally THIS (that is default)> }
Supported Scopes: all

spawn_random_anomaly.description:
Spawn a random anomaly on the scoped planet
spawn_random_anomaly = {
	target = root.owner
	surveyor = event_target:arkship
}
Supported Scopes: all

add_variable.description:
Increments a previously-set variable by a specific amount
add_variable = { which = <string> value = <float>/<variable>/<scope.variable>/trigger:<trigger> }
Supported Scopes: megastructure planet country ship pop pop_group fleet galactic_object leader army ambient_object species bypass pop_faction war federation starbase deposit sector archaeological_site first_contact spy_network espionage_operation espionage_asset agreement situation astral_rift ship_growth_stage colony

displace_pop_amount.description:
Raises on_pop_displaced on_action
displace_pop_amount = {
	amount = <amount> OR percentage = <percentage>
	random = <number> (optional) If set, the amount will be randomized in [max(0, size - random), size + random].
}
Supported Scopes: pop_group

create_rebels.description:
Creates a rebellion
create_rebels = {
	name = <random / string>
	authority = <random / key>
	civics = random / { civic = <key> civic = random }
	species = <target>
	ethos = <random / { ethic = <key> ethic = <key> }
}
Supported Scopes: planet ship colony

while.description:
Repeats enclosed effects while limit criteria are met or until set iteration count is reached
while = { limit = { <triggers> } <effects> }
 while = { count = [3|Variable] <effects> }
Supported Scopes: all

every_system_in_cluster.description:
Executes enclosed effects on every system in the cluster that meet the limit criteria
every_system_in_cluster = { limit = { <triggers> } <effects> }
Supported Scopes: all

set_timed_pop_faction_flag.description:
Sets an arbitrarily-named flag on the scoped pop faction for a set duration
set_timed_pop_faction_flag = {
	flag = <key> (note: one can use <key>@scope e.g. my_flag@from to track relationships between objects)
	days = <int>
}
Supported Scopes: pop_faction

add_tech_progress.description:
Gives percentage progress (0.0-1.0) in a specific tech to the scoped country
add_tech_progress = { tech = <key> progress = <float>/<variable> }
Supported Scopes: country

set_council_position_title_male.description:
Sets the scoped country's council position's male title.
set_council_position_title_male = { position_tag = COUNCIL_POSITION_TAG title = TITLE_MALE }
Supported Scopes: country

set_council_position_title_female.description:
Sets the scoped country's council position's female title.
set_council_position_title_female = { position_tag = COUNCIL_POSITION_TAG title = TITLE_FEMALE }
Supported Scopes: country

abort_special_project.description:
Aborts a specific special project for the country, removing it from the situation log
abort_special_project = { type = <project key> location = <target> }
Supported Scopes: country

set_ai_ship_roles.description:
Sets the AI ship role overrides for the scoped country.
set_ai_ship_roles = { corvette = gunship destroyer = { artillery = 70 gunship = 30 } }
Supported Scopes: country

move_system.description:
Moves scoped system to a position relative to the given system/planet/ship.
move_system = { target = <system/planet/ship> min_jumps = <value> max_jumps = <value> min_distance = <int 0-100> max_distance = <int 0-100> hyperlane=<yes/no> reset_terra_incognita = <yes/no>}
Supported Scopes: galactic_object

add_stage_modifier.description:
Adds a specific modifier to the target's current stage for a set duration or until stage is changed
add_stage_modifier = { modifier = <key> days = <int>, -1 means it never expires> }
Supported Scopes: espionage_operation astral_rift

add_intel_report.description:
Adds the intel level for the category selected. Default duration (0) is forever.
add_intel_report = { category = <string> level = <int> days = <int> who = <target> }
Supported Scopes: country

clear_intel_report.description:
Removes all the intel reports related to the provided category.
clear_intel_report = { category = <string> who = <target> }
Supported Scopes: country

join_alliance.description:
Join federation with target
join_alliance = { who = <target> override_requirements = yes/no }
Supported Scopes: country

give_fleet.description:
Leases fleet out to the new controller country for a numbed of days 
give_fleet = {
	controller = <target country> 
	days = <number of days>
}
Supported Scopes: fleet

prolong_fleet_contract.description:
Prolongs fleet's lease contract for a numbed of days 
prolong_fleet_contract = { days = <number of days> }
Supported Scopes: fleet

set_fleet_settings.description:
Set fleet's settings, any unspecified setting will set to default value.
set_fleet_settings = { can_upgrade = no can_change_leader = no ... }
Supported Scopes: fleet

enable_mission.description:
Enables a mission for target country
 enable_mission = { name = <mission key> }
Supported Scopes: all

propose_resolution.description:
Proposes the resolution of the given type
ppropose_resolution = {
	resolution = <resolution type>
	target = <event_target:country> (optional)}
Supported Scopes: country

set_trade_conversions.description:
Sets the trade conversions for the scoped Country. If they do not add up to 1.0 any remaining trade the country keeps as income
set_trade_conversion = { energy = 0.5 minerals = 0.2 }
Supported Scopes: country

set_resource.description:
Sets the specific resource to the stockpile for the country scope:
set_resource = {
	resource = <resource_name>
	value = <variable>
}
Supported Scopes: country

create_balanced_fleet.description:
Creates a fleet of the requested size, distributing ships deterministically across the listed designs by each ship_size's ai_ship_data.fraction.
create_balanced_fleet = {
	name = <string>
	size = <int>
	can_overflow = yes/no # default yes
	ship_designs = { NAME_a NAME_b } # optional; if omitted, uses the country's own designs
	effect = { <set_location etc effects go here> }
}
Supported Scopes: country

else.description:
Executes enclosed effects if limit criteria of preceding 'if' or 'else_if' is not met
if = { limit = { <triggers> } <effects> }
else = { <effects> }
Supported Scopes: all

inverted_switch.description:
Executes the first appropriate effect set for a specific trigger treated as NOT.
inverted_switch = {
	trigger = <trigger>
	<corresponding key/bool/int> = { <effect> }
	<corresponding key/bool/int> > (less/greater than appear 'reversed') { <effect> }
	default = { <effect> }
}
Supported Scopes: all

random_agreement.description:
Iterate through each agreement - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_agreement = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: country no_scope

ordered_agreement.description:
Iterate through each agreement - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_agreement = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: country no_scope

every_agreement.description:
Iterate through each agreement - executes the enclosed effects on all of them for which the limit triggers return true
every_agreement = { limit = { <triggers> } <effects> }
Supported Scopes: country no_scope

random_ambient_object.description:
Iterate through every ambient object in the game - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_ambient_object = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: all

ordered_ambient_object.description:
Iterate through every ambient object in the game - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_ambient_object = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: all

every_ambient_object.description:
Iterate through every ambient object in the game - executes the enclosed effects on all of them for which the limit triggers return true
every_ambient_object = { limit = { <triggers> } <effects> }
Supported Scopes: all

random_system_ambient_object.description:
Iterate through every ambient object in the solar system - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_system_ambient_object = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: galactic_object

ordered_system_ambient_object.description:
Iterate through every ambient object in the solar system - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_system_ambient_object = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: galactic_object

every_system_ambient_object.description:
Iterate through every ambient object in the solar system - executes the enclosed effects on all of them for which the limit triggers return true
every_system_ambient_object = { limit = { <triggers> } <effects> }
Supported Scopes: galactic_object

random_archaeological_site.description:
Iterate through every archaeological sites - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_archaeological_site = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: all

ordered_archaeological_site.description:
Iterate through every archaeological sites - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_archaeological_site = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: all

every_archaeological_site.description:
Iterate through every archaeological sites - executes the enclosed effects on all of them for which the limit triggers return true
every_archaeological_site = { limit = { <triggers> } <effects> }
Supported Scopes: all

random_owned_army.description:
Iterate through each army that is owned by the country - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_owned_army = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: country

ordered_owned_army.description:
Iterate through each army that is owned by the country - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_owned_army = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: country

every_owned_army.description:
Iterate through each army that is owned by the country - executes the enclosed effects on all of them for which the limit triggers return true
every_owned_army = { limit = { <triggers> } <effects> }
Supported Scopes: country

random_planet_army.description:
Iterate through each army on the colony (not in ground combat), regardless of owner. - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_planet_army = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: planet ship colony

ordered_planet_army.description:
Iterate through each army on the colony (not in ground combat), regardless of owner. - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_planet_army = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: planet ship colony

every_planet_army.description:
Iterate through each army on the colony (not in ground combat), regardless of owner. - executes the enclosed effects on all of them for which the limit triggers return true
every_planet_army = { limit = { <triggers> } <effects> }
Supported Scopes: planet ship colony

random_ground_combat_attacker.description:
Iterate through each army currently attacking the colony in ground combat - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
random_ground_combat_attacker = {
	limit = { <triggers> }
	weights = { (optional - adds weights to affect the chance a specific object is selected)
		base = float
		modifier = { <add/factor = float> <triggers> }
	}
	<effects>
}
Supported Scopes: planet ship colony

ordered_ground_combat_attacker.description:
Iterate through each army currently attacking the colony in ground combat - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
ordered_ground_combat_attacker = {
	limit = { <triggers> }
	position = <integer, starting with 0>
	order_by = <variable>/trigger:<trigger>
	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
	<effects>
}
Supported Scopes: planet ship colony

every_ground_combat_attacker.description:
Iterate through each army currently attacking the colony in ground combat - executes the enclosed effects on all of them for which the limit triggers return true
every_ground_combat_attacker = { limit = { <triggers> } <effects> }
Supported Scopes: planet ship colony

random_ground_combat_defender.description:
